examples.template:
MonarchLinkedDocsPanel(
    items,
    docOptions: [
        MonarchLinkedDocsPanelOption(docID: {{docOptions.0.value}}, label: {{docOptions.0.label}}, description: {{docOptions.0.description}}),
        MonarchLinkedDocsPanelOption(docID: {{docOptions.1.value}}, label: {{docOptions.1.label}}, description: {{docOptions.1.description}}),
        MonarchLinkedDocsPanelOption(docID: {{docOptions.2.value}}, label: {{docOptions.2.label}}, description: {{docOptions.2.description}}),
    ],
    onLinkDoc: { docID in
        items.append(MonarchLinkedDocsPanelItem(id: docID, title: docID, docID: docID))
    },
    onCreateDoc: {},
    onAddLink: { url, title in
        items.append(MonarchLinkedDocsPanelItem(id: url.absoluteString, title: title, kind: .link, url: url))
    },
    onUnlink: { item in
        items.removeAll { $0.id == item.id }
    },
    onOpen: { opened = $0.title }
)

